function setPositionLeverage(address account, uint256 subaccount, uint256 newLeverage) external onlySenderOrOperator(account, PerpsOperatorRoles.SET_LEVERAGE) {
    ClearingHouse storage clearingHouse = StorageLib.loadClearingHouse();

    __MarginUpdateCache__ memory cache;

    // load account
    (cache.assets, cache.positions) = clearingHouse.getAccount(account, subaccount);

    if (newLeverage == 0) revert InvalidLeverage();
    if (cache.positions.length == 0) revert InvalidLeverage();

    // realize funding payment
    cache.fundingPayment = ClearingHouseLib.realizeFundingPayment(cache.assets, cache.positions);

    // calculate intended margin based on new leverage
    uint256 intendedMargin = calculateIntendedMargin(cache.positions, newLeverage);

    // ensure the intended margin is covered by existing margin
    int256 remainingMargin = StorageLib.loadCollateralManager().settleMarginUpdate({
        account: account,
        subaccount: subaccount,
        marginDelta: 0, // no margin change, just checking
        fundingPayment: cache.fundingPayment
    });

    // assert post leverage change margin requirement
    clearingHouse.assertPostLeverageChangeMarginRequired({
        assets: cache.assets,
        positions: cache.positions,
        margin: remainingMargin,
        intendedMargin: intendedMargin
    });

    // update leverage
    clearingHouse.updateLeverage({
        account: account,
        subaccount: subaccount,
        newLeverage: newLeverage
    });

    emit LeverageUpdated(account, subaccount, newLeverage, remainingMargin, StorageLib.incNonce());
}

